cd /home/judge/solution && set -a && . deploy/compose/.env && set +a && curl -s -u ditto:$DITTO_PASSWORD "http://127.0.0.1:$DITTO_PORT/api/2/search/things?filter=like(thingId,%22kz.limit:*%22)&option=size(200)" > /tmp/a.json; sleep 60; curl -s -u ditto:$DITTO_PASSWORD "http://127.0.0.1:$DITTO_PORT/api/2/search/things?filter=like(thingId,%22kz.limit:*%22)&option=size(200)" > /tmp/b.json; python3 -c "
import json
a={t['thingId']:t for t in json.load(open('/tmp/a.json'))['items']}
b={t['thingId']:t for t in json.load(open('/tmp/b.json'))['items']}
for k in a:
  at=a[k].get('attributes',{}); print(k, {x:at[x] for x in at if x in ('_parents','ore_to','water_to','water_from','power_from')})
  for f,v in a[k].get('features',{}).items():
    if f in ('events','schedule','setpoint','advice'): 
      print('   ',f,str(v['properties'].get('value'))[:300]); continue
    print('   ',f, v['properties'].get('value'),'->', b[k]['features'].get(f,{}).get('properties',{}).get('value'))
"

